'use client';

import React, { useEffect, useState } from 'react';
import { api } from '@/lib/api';
import { ConversationMember, Message } from '@/types/chat';
import { Avatar } from '@/components/ui/Avatar';
import { formatTime, formatTimeAgo } from '@/lib/utils';
import { Search, X, Loader2, FileText, CornerDownRight } from 'lucide-react';

interface EmbeddedChatSearchProps {
  conversationId: string;
  members: ConversationMember[];
  onSelectMessage?: (message: Message) => void;
}

export const EmbeddedChatSearch: React.FC<EmbeddedChatSearchProps> = ({
  conversationId,
  members,
  onSelectMessage,
}) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Message[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      setIsSearching(false);
      return;
    }

    let active = true;
    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const res = await api.searchMessages(conversationId, query.trim());
        if (active && res.data) {
          setResults(res.data);
          setSearchError('');
        }
      } catch (err: unknown) {
        if (active) setSearchError(err instanceof Error ? err.message : 'Search failed. Try again.');
      } finally {
        if (active) setIsSearching(false);
      }
    }, 250);

    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [query, conversationId]);

  const highlightMatch = (text: string, q: string) => {
    if (!q.trim()) return text;
    const regex = new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    const parts = text.split(regex);
    return parts.map((part, i) =>
      part.toLowerCase() === q.toLowerCase() ? (
        <mark
          key={i}
          style={{
            backgroundColor: 'var(--warning-light)',
            color: 'var(--warning)',
            padding: '1px 3px',
            borderRadius: '3px',
          }}
        >
          {part}
        </mark>
      ) : (
        part
      )
    );
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      {/* Search Input Bar */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          background: 'var(--bg-tertiary)',
          border: '1px solid var(--border-subtle)',
          borderRadius: '10px',
          padding: '8px 12px',
        }}
      >
        <Search size={16} style={{ color: 'var(--text-muted)', flexShrink: 0 }} />
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search words, phrases, or topics..."
          style={{
            background: 'transparent',
            border: 'none',
            outline: 'none',
            color: 'var(--text-primary)',
            fontSize: '0.867rem',
            width: '100%',
          }}
          autoFocus
        />
        {query && (
          <button
            type="button"
            onClick={() => setQuery('')}
            style={{
              background: 'transparent',
              border: 'none',
              color: 'var(--text-muted)',
              cursor: 'pointer',
              padding: '2px',
            }}
          >
            <X size={15} />
          </button>
        )}
      </div>

      {/* Results Header */}
      {query.trim() && !isSearching && (
        <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', paddingLeft: '2px' }}>
          {results.length === 1 ? '1 matching message' : `${results.length} matching messages`}
        </div>
      )}

      {/* Search Results List */}
      <div
        style={{
          maxHeight: '340px',
          overflowY: 'auto',
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          paddingRight: '2px',
        }}
      >
        {isSearching ? (
          <div style={{ padding: '32px 16px', textAlign: 'center', color: 'var(--text-muted)' }}>
            <Loader2 size={22} className="animate-spin" style={{ margin: '0 auto 8px' }} />
            <span style={{ fontSize: '0.82rem' }}>Searching messages...</span>
          </div>
        ) : !query.trim() ? (
          <div
            style={{
              padding: '40px 16px',
              textAlign: 'center',
              color: 'var(--text-muted)',
              background: 'var(--bg-tertiary)',
              borderRadius: 'var(--radius-md)',
              border: '1px dashed var(--border-subtle)',
            }}
          >
            <Search size={28} style={{ margin: '0 auto 8px', opacity: 0.5 }} />
            <p style={{ fontWeight: 600, fontSize: '0.88rem', color: 'var(--text-secondary)' }}>
              Search in this chat
            </p>
            <p style={{ fontSize: '0.78rem', marginTop: '4px' }}>
              Find past messages, notes, and references instantly.
            </p>
          </div>
        ) : results.length === 0 ? (
          <div style={{ padding: '32px 16px', textAlign: 'center', color: 'var(--text-muted)' }}>
            {searchError || 'No messages match your search term.'}
          </div>
        ) : (
          results.map((msg) => {
            const sender = members.find((m) => m.user_id === msg.sender_id);
            const senderName =
              sender?.profiles?.display_name ||
              sender?.profiles?.username ||
              'User';
            const senderAvatar = sender?.profiles?.avatar_key;

            return (
              <div
                key={msg.id}
                onClick={() => onSelectMessage?.(msg)}
                style={{
                  display: 'flex',
                  gap: '10px',
                  padding: '10px 12px',
                  borderRadius: '10px',
                  background: 'var(--bg-tertiary)',
                  border: '1px solid var(--border-subtle)',
                  cursor: onSelectMessage ? 'pointer' : 'default',
                  transition: 'background 0.15s ease',
                }}
                onMouseEnter={(e) => {
                  if (onSelectMessage) e.currentTarget.style.background = 'var(--bg-glass-hover)';
                }}
                onMouseLeave={(e) => {
                  if (onSelectMessage) e.currentTarget.style.background = 'var(--bg-tertiary)';
                }}
              >
                <Avatar name={senderName} src={senderAvatar} size="sm" />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      marginBottom: '3px',
                    }}
                  >
                    <span style={{ fontSize: '0.82rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                      {senderName}
                    </span>
                    <span style={{ fontSize: '0.72rem', color: 'var(--text-muted)' }}>
                      {formatTimeAgo(msg.created_at)}
                    </span>
                  </div>
                  <div
                    style={{
                      fontSize: '0.82rem',
                      lineHeight: '1.35',
                      color: 'var(--text-secondary)',
                      wordBreak: 'break-word',
                    }}
                  >
                    {highlightMatch(msg.body, query)}
                  </div>
                  {msg.attachments && msg.attachments.length > 0 && (
                    <div
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '4px',
                        marginTop: '6px',
                        padding: '2px 6px',
                        borderRadius: '4px',
                        background: 'var(--bg-tertiary)',
                        fontSize: '0.7rem',
                        color: 'var(--text-muted)',
                      }}
                    >
                      <FileText size={12} />
                      <span>{msg.attachments.length} attachment(s)</span>
                    </div>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

'use client';

import { Avatar } from '@/components/ui/Avatar';
import { useToast } from '@/components/ui/Toast';
import { api } from '@/lib/api';
import { formatFileSize,formatTime,getMemberProfile } from '@/lib/utils';
import { Attachment,ConversationMember,Message } from '@/types/chat';
import {
  Check,
  CheckCheck,
  Copy,
  Download,
  Edit2,
  FileText,
  MoreHorizontal,
  Save,
  Trash2,
  X
} from 'lucide-react';
import Image from 'next/image';
import React,{ useEffect,useId,useRef,useState } from 'react';

interface MessageItemProps {
  message: Message;
  currentUserId: string;
  members: ConversationMember[];
  isConsecutive?: boolean;
  onToggleReaction: (messageId: string, emoji: string) => Promise<void>;
  onEditMessage: (messageId: string, body: string) => Promise<void>;
  onDeleteMessage: (messageId: string) => Promise<void>;
  onOpenUserProfile?: (userId: string, profile?: any) => void;
}

const QUICK_EMOJIS = ['👍', '❤️', '🔥', '😂', '🎉', '🚀'];

export const MessageItem: React.FC<MessageItemProps> = ({
  message,
  currentUserId,
  members,
  isConsecutive = false,
  onToggleReaction,
  onEditMessage,
  onDeleteMessage,
  onOpenUserProfile,
}) => {
  const { error, success } = useToast();
  const isMe = message.sender_id === currentUserId;
  const isDeleted = !!message.deleted_at;

  const [actionsOpen, setActionsOpen] = useState(false);
  const actionsId = useId();
  const actionsTrigger = useRef<HTMLButtonElement>(null);
  const touchTimerRef = useRef<NodeJS.Timeout | null>(null);
  const touchStartPosRef = useRef<{ x: number; y: number } | null>(null);
  const isLongPressRef = useRef(false);

  useEffect(() => () => {
    if (touchTimerRef.current) clearTimeout(touchTimerRef.current);
  }, []);

  // Close actions menu when clicking outside on desktop
  useEffect(() => {
    if (!actionsOpen) return;
    const handleOutsideClick = (e: MouseEvent) => {
      if (
        actionsTrigger.current &&
        !actionsTrigger.current.contains(e.target as Node)
      ) {
        const menuEl = document.getElementById(actionsId);
        if (menuEl && !menuEl.contains(e.target as Node)) {
          setActionsOpen(false);
        }
      }
    };
    document.addEventListener('mousedown', handleOutsideClick);
    return () => {
      document.removeEventListener('mousedown', handleOutsideClick);
    };
  }, [actionsOpen, actionsId]);

  const handleTouchStart = (e: React.TouchEvent) => {
    if (isDeleted || isEditing) return;
    const touch = e.touches[0];
    touchStartPosRef.current = { x: touch.clientX, y: touch.clientY };
    isLongPressRef.current = false;

    if (touchTimerRef.current) clearTimeout(touchTimerRef.current);
    touchTimerRef.current = setTimeout(() => {
      isLongPressRef.current = true;
      setActionsOpen(true);
      if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
        try { navigator.vibrate(35); } catch {}
      }
    }, 450);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (!touchStartPosRef.current) return;
    const touch = e.touches[0];
    const dx = Math.abs(touch.clientX - touchStartPosRef.current.x);
    const dy = Math.abs(touch.clientY - touchStartPosRef.current.y);
    if (dx > 10 || dy > 10) {
      if (touchTimerRef.current) {
        clearTimeout(touchTimerRef.current);
        touchTimerRef.current = null;
      }
    }
  };

  const handleTouchEnd = () => {
    if (touchTimerRef.current) {
      clearTimeout(touchTimerRef.current);
      touchTimerRef.current = null;
    }
    touchStartPosRef.current = null;
    setTimeout(() => {
      isLongPressRef.current = false;
    }, 150);
  };

  const handleContextMenu = (e: React.MouseEvent) => {
    if (isDeleted || isEditing) return;
    e.preventDefault();
    setActionsOpen(true);
  };

  const handleCopy = async () => {
    if (!message.body) return;
    try {
      await navigator.clipboard.writeText(message.body);
      success('Copied to clipboard');
    } catch {
      error('Failed to copy message');
    }
  };
  const [isEditing, setIsEditing] = useState(false);
  const [editBody, setEditBody] = useState(message.body);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const [signedUrls, setSignedUrls] = useState<Record<string, string>>({});
  const [loadingUrls, setLoadingUrls] = useState<Record<string, boolean>>({});

  // Sender profile
  const senderMember = members.find((m) => m.user_id === message.sender_id);
  const senderProfile = getMemberProfile(senderMember);
  const senderName =
    senderProfile?.display_name ||
    senderProfile?.username ||
    'Student';
  const senderAvatar = senderProfile?.avatar_key;

  // Determine read status: did any other active member read past this message's seq?
  const isReadByOthers = members.some(
    (m) => m.user_id !== currentUserId && !m.left_at && m.last_read_seq >= message.seq
  );

  // Load signed URLs for attachments
  const fetchAttachmentUrl = async (attachment: Attachment) => {
    if (signedUrls[attachment.id] || loadingUrls[attachment.id]) return;

    setLoadingUrls((prev) => ({ ...prev, [attachment.id]: true }));
    try {
      const res = await api.getAttachmentUrl(attachment.id);
      if (res.data?.signedUrl) {
        setSignedUrls((prev) => ({ ...prev, [attachment.id]: res.data.signedUrl }));
      }
    } catch (err: unknown) {
      console.error('Failed to get attachment URL:', err);
    } finally {
      setLoadingUrls((prev) => ({ ...prev, [attachment.id]: false }));
    }
  };

  useEffect(() => {
    let active = true;
    if (!isDeleted) {
      for (const attachment of message.attachments || []) {
        if (!/^(image|audio)\//.test(attachment.mime_type)) continue;
        api.getAttachmentUrl(attachment.id).then(res => {
          if (active && res.data?.signedUrl) setSignedUrls(previous => ({ ...previous, [attachment.id]: res.data.signedUrl }));
        }).catch(() => {});
      }
    }
    return () => { active = false; };
  }, [message.attachments, isDeleted]);

  // Aggregate reactions: emoji -> { count, hasReacted }
  const reactionGroups: { emoji: string; count: number; hasReacted: boolean }[] = [];
  if (message.message_reactions && message.message_reactions.length > 0) {
    const map = new Map<string, { count: number; hasReacted: boolean }>();
    for (const r of message.message_reactions) {
      const existing = map.get(r.emoji) || { count: 0, hasReacted: false };
      existing.count += 1;
      if (r.user_id === currentUserId) {
        existing.hasReacted = true;
      }
      map.set(r.emoji, existing);
    }
    map.forEach((val, emoji) => {
      reactionGroups.push({ emoji, count: val.count, hasReacted: val.hasReacted });
    });
  }

  const handleSaveEdit = async () => {
    if (!editBody.trim()) {
      error('Message text cannot be empty');
      return;
    }
    setIsSavingEdit(true);
    try {
      await onEditMessage(message.id, editBody.trim());
      setIsEditing(false);
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to edit message');
    } finally {
      setIsSavingEdit(false);
    }
  };

  const handleDelete = async () => {
    if (confirm('Are you sure you want to delete this message?')) {
      try {
        await onDeleteMessage(message.id);
      } catch (err: unknown) {
        error((err instanceof Error ? err.message : '') || 'Failed to delete message');
      }
    }
  };

  const handleReaction = async (emoji: string) => {
    try { await onToggleReaction(message.id, emoji); }
    catch (err) { error(err instanceof Error ? err.message : 'Could not update reaction.'); }
  };

  return (
    <div
      className={`message-row ${isMe ? 'sent' : 'received'} ${isConsecutive ? 'consecutive' : ''} ${actionsOpen ? 'actions-open' : ''}`}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && actionsOpen) {
          event.stopPropagation();
          setActionsOpen(false);
          actionsTrigger.current?.focus();
        }
      }}
    >
      {!isMe && (
        isConsecutive ? (
          <div className="message-avatar-spacer" aria-hidden="true" />
        ) : (
          <div
            onClick={() => onOpenUserProfile?.(message.sender_id, senderProfile)}
            style={{ cursor: 'pointer' }}
            title={`View ${senderName}'s profile`}
          >
            <Avatar name={senderName} src={senderAvatar} size="sm" />
          </div>
        )
      )}

      <div className="message-content-wrapper" >
        <div
          className={`message-bubble ${isDeleted ? 'deleted' : ''}`}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
          onTouchCancel={handleTouchEnd}
          onContextMenu={handleContextMenu}
          onClick={(e) => {
            if (isLongPressRef.current) {
              e.preventDefault();
              e.stopPropagation();
            }
          }}
        >
          {/* Sender name for received messages in group chats */}
          {!isMe && !isConsecutive && (
            <div
              className="message-sender-name"
              onClick={(e) => {
                e.stopPropagation();
                onOpenUserProfile?.(message.sender_id, senderProfile);
              }}
              style={{ cursor: 'pointer' }}
              title={`View ${senderName}'s profile`}
            >
              {senderName}
            </div>
          )}

          {/* Deleted tombstone */}
          {isDeleted ? (
            <div className="message-text">This message was deleted</div>
          ) : isEditing ? (
            <div className="message-edit">
              <textarea
                value={editBody}
                onChange={(e) => setEditBody(e.target.value)}
                aria-label="Edit message"
                className="input-control message-edit-input"
                rows={2}
              />
              <div style={{ display: 'flex', gap: '6px', justifyContent: 'flex-end', marginTop: '6px' }}>
                <button
                  onClick={() => setIsEditing(false)}
                  className="btn btn-ghost"
                  style={{ padding: '4px 8px', fontSize: '0.8rem' }}
                >
                  <X size={12} />
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  disabled={isSavingEdit}
                  className="btn btn-primary"
                  style={{ padding: '4px 10px', fontSize: '0.8rem' }}
                >
                  <Save size={12} />
                  {isSavingEdit ? 'Saving...' : 'Save'}
                </button>
              </div>
            </div>
          ) : (
            <>
              {/* Message text */}
              {message.body && (
                <div className="message-text">{message.body}</div>
              )}

              {/* Attachments */}
              {message.attachments && message.attachments.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '4px' }}>
                  {message.attachments.map((att) => {
                    const isImage = att.mime_type.startsWith('image/');
                    const isAudio = att.mime_type.startsWith('audio/');
                    const url = signedUrls[att.id];

                    if (isImage) {
                      return (
                        <div key={att.id} style={{ position: 'relative' }}>
                          {url ? (
                            <a href={url} target="_blank" rel="noopener noreferrer">
                              <Image unoptimized width={320} height={260}
                                src={url}
                                alt={att.original_name}
                                className="attachment-img-preview"
                              />
                            </a>
                          ) : (
                            <div
                              onClick={() => fetchAttachmentUrl(att)}
                              className="attachment-card"
                              role="button"
                              tabIndex={0}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter' || e.key === ' ') {
                                  e.preventDefault();
                                  void fetchAttachmentUrl(att);
                                }
                              }}
                            >
                              <FileText size={18} className="attachment-icon" />
                              <span className="attachment-filename">{att.original_name} (Click to load image)</span>
                            </div>
                          )}
                        </div>
                      );
                    }

                    if (isAudio && url) {
                      return (
                        <div key={att.id} style={{ marginTop: '4px' }}>
                          <audio controls src={url} style={{ maxWidth: '240px', height: '36px' }} />
                        </div>
                      );
                    }

                    return (
                      <div
                        key={att.id}
                        onClick={async () => {
                          if (url) {
                            window.open(url, '_blank');
                          } else {
                            await fetchAttachmentUrl(att);
                          }
                        }}
                        className="attachment-card"
                        role="button"
                        tabIndex={0}
                        onKeyDown={async (e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault();
                            if (url) window.open(url, '_blank');
                            else await fetchAttachmentUrl(att);
                          }
                        }}
                      >
                        <FileText size={18} className="attachment-icon" />
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div className="attachment-filename">
                            {att.original_name}
                          </div>
                          <div className="attachment-filesize">
                            {formatFileSize(att.size_bytes)}
                          </div>
                        </div>
                        <Download size={15} className="attachment-download-icon" />
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}

          {/* Message Meta (time, edited, read checkmarks) */}
          <div className="message-meta">
            {message.edited_at && !isDeleted && (
              <span className="message-edited-tag">edited</span>
            )}
            <span>{formatTime(message.created_at)}</span>
            {isMe && !isDeleted && (
              <span title={isReadByOthers ? 'Read' : 'Sent'}>
                {isReadByOthers ? (
                  <CheckCheck size={13} color="currentColor" />
                ) : (
                  <Check size={13} color="currentColor" />
                )}
              </span>
            )}
          </div>
        </div>

        {/* Hover Action Menu */}
        {!isDeleted && !isEditing && (
          <>
            <button
              ref={actionsTrigger}
              className="message-actions-trigger"
              aria-label="Message actions"
              aria-expanded={actionsOpen}
              aria-controls={actionsId}
              onClick={() => setActionsOpen(!actionsOpen)}
              type="button"
            >
              <MoreHorizontal size={18} />
            </button>

            {actionsOpen && (
              <div
                className="message-actions-backdrop"
                onClick={() => setActionsOpen(false)}
                aria-hidden="true"
              />
            )}

            <div
              id={actionsId}
              className={`message-hover-actions ${actionsOpen ? 'open' : ''}`}
              role="group"
              aria-label="Message actions"
            >
              <div className="message-actions-emojis">
                {QUICK_EMOJIS.map((emoji) => (
                  <button
                    key={emoji}
                    onClick={() => {
                      void handleReaction(emoji);
                      setActionsOpen(false);
                    }}
                    className="action-btn-mini"
                    title={`React with ${emoji}`}
                    type="button"
                  >
                    {emoji}
                  </button>
                ))}
              </div>

              <div className="message-actions-tools">
                {message.body && (
                  <button
                    onClick={() => {
                      setActionsOpen(false);
                      void handleCopy();
                    }}
                    className="action-btn-mini"
                    title="Copy message"
                    type="button"
                  >
                    <Copy size={13} />
                    <span className="action-btn-label">Copy</span>
                  </button>
                )}
                {isMe && (
                  <>
                    <button
                      onClick={() => {
                        setActionsOpen(false);
                        setEditBody(message.body);
                        setIsEditing(true);
                      }}
                      className="action-btn-mini"
                      title="Edit message"
                      type="button"
                    >
                      <Edit2 size={13} />
                      <span className="action-btn-label">Edit</span>
                    </button>
                    <button
                      onClick={() => {
                        setActionsOpen(false);
                        void handleDelete();
                      }}
                      className="action-btn-mini action-btn-danger"
                      title="Delete message"
                      type="button"
                    >
                      <Trash2 size={13} />
                      <span className="action-btn-label">Delete</span>
                    </button>
                  </>
                )}
              </div>
            </div>
          </>
        )}

        {/* Reaction Badges */}
        {reactionGroups.length > 0 && !isDeleted && (
          <div className="reactions-row">
            {reactionGroups.map((rg) => (
              <button
                key={rg.emoji}
                onClick={() => handleReaction(rg.emoji)}
                className={`reaction-pill ${rg.hasReacted ? 'active' : ''}`}
                title={`Reacted by ${rg.count} user(s)`}
              >
                <span>{rg.emoji}</span>
                <span className="reaction-count">{rg.count}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

'use client';

import { formatDateDivider } from '@/lib/utils';
import { ConversationMember,Message } from '@/types/chat';
import { ArrowDown,MessageSquare } from 'lucide-react';
import React,{ useEffect,useLayoutEffect,useRef,useState } from 'react';
import { MessageItem } from './MessageItem';

interface MessageListProps {
  messages: Message[];
  currentUserId: string;
  members: ConversationMember[];
  typingUserIds: string[];
  hasMore: boolean;
  isLoadingMore: boolean;
  onLoadMore: () => Promise<void>;
  onToggleReaction: (messageId: string, emoji: string) => Promise<void>;
  onEditMessage: (messageId: string, body: string) => Promise<void>;
  onDeleteMessage: (messageId: string) => Promise<void>;
  onOpenUserProfile?: (userId: string, profile?: any) => void;
}

export const MessageList: React.FC<MessageListProps> = ({
  messages,
  currentUserId,
  members,
  typingUserIds,
  hasMore,
  isLoadingMore,
  onLoadMore,
  onToggleReaction,
  onEditMessage,
  onDeleteMessage,
  onOpenUserProfile,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const bottomRef = useRef<HTMLDivElement>(null);
  const [showScrollBottom, setShowScrollBottom] = useState(false);
  const isAutoScrollPaused = useRef(false);
  const olderScroll = useRef<{ height: number; top: number } | null>(null);
  const olderLoading = useRef(false);
  const loadOlder = async () => {
    if (olderLoading.current || isLoadingMore) return;
    const container = containerRef.current;
    if (container) olderScroll.current = { height: container.scrollHeight, top: container.scrollTop };
    olderLoading.current = true;
    isAutoScrollPaused.current = true;
    try { await onLoadMore(); }
    finally { olderLoading.current = false; }
  };
  useLayoutEffect(() => {
    const container = containerRef.current;
    const position = olderScroll.current;
    if (container && position && !isLoadingMore) {
      container.scrollTop = position.top + container.scrollHeight - position.height;
      olderScroll.current = null;
    }
  }, [messages, isLoadingMore]);

  // Group messages by date
  const groupedMessages: { date: string; items: Message[] }[] = [];
  let currentDate = '';
  let currentGroup: Message[] = [];

  for (const msg of messages) {
    const dateLabel = formatDateDivider(msg.created_at);
    if (dateLabel !== currentDate) {
      if (currentGroup.length > 0) {
        groupedMessages.push({ date: currentDate, items: currentGroup });
      }
      currentDate = dateLabel;
      currentGroup = [msg];
    } else {
      currentGroup.push(msg);
    }
  }
  if (currentGroup.length > 0) {
    groupedMessages.push({ date: currentDate, items: currentGroup });
  }

  // Scroll to bottom on load / message add
  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    const reduced = document.documentElement.dataset.reduceMotion === 'true' || matchMedia('(prefers-reduced-motion: reduce)').matches;
    bottomRef.current?.scrollIntoView({ behavior: reduced ? 'auto' : behavior, block: 'end' });
  };

  useEffect(() => {
    if (!isAutoScrollPaused.current) {
      scrollToBottom('smooth');
    }
  }, [messages.length, typingUserIds.length]);

  const handleScroll = () => {
    if (!containerRef.current) return;
    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;
    const distanceFromBottom = scrollHeight - (scrollTop + clientHeight);

    setShowScrollBottom(distanceFromBottom > 150);
    isAutoScrollPaused.current = distanceFromBottom > 150;

    // Trigger load more when near top
    if (scrollTop < 50 && hasMore && !isLoadingMore) {
      void loadOlder();
    }
  };

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      className="messages-container"
    >
      {/* Load older messages button if available */}
      {hasMore && (
        <div style={{ textAlign: 'center', margin: '8px 0' }}>
          <button
            onClick={loadOlder}
            disabled={isLoadingMore}
            className="btn btn-secondary"
            style={{ fontSize: '0.8rem', padding: '6px 14px', borderRadius: 'var(--radius-full)' }}
          >
            {isLoadingMore ? 'Loading older messages...' : 'Load older messages'}
          </button>
        </div>
      )}

      {/* Empty / Loading State */}
      {messages.length === 0 ? (
        isLoadingMore ? (
          <div className="message-skeleton-container" aria-label="Loading messages" role="status">
            {[
              { align: 'left', width: '52%', lines: 2 },
              { align: 'right', width: '38%', lines: 1 },
              { align: 'left', width: '68%', lines: 3 },
              { align: 'right', width: '46%', lines: 1 },
              { align: 'left', width: '34%', lines: 1 },
            ].map((s, idx) => (
              <div
                key={idx}
                className={`message-skeleton-row ${s.align === 'right' ? 'skeleton-sent' : 'skeleton-received'}`}
              >
                {s.align === 'left' && <div className="message-skeleton-avatar shimmer-box" />}
                <div
                  className="message-skeleton-bubble"
                  style={{ width: s.width }}
                >
                  <div className="shimmer-box skeleton-line-title" />
                  {s.lines >= 2 && <div className="shimmer-box skeleton-line-body" />}
                  {s.lines >= 3 && <div className="shimmer-box skeleton-line-body short" />}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="empty-state">
            <div className="empty-state-icon">
              <MessageSquare size={28} />
            </div>
            <h3 className="empty-state-title">No messages yet</h3>
            <p className="empty-state-desc">
              Send a message to start this conversation. New messages appear here in real time.
            </p>
          </div>
        )
      ) : (
        groupedMessages.map((group) => (
          <React.Fragment key={group.date}>
            <div className="date-divider">
              <span className="date-divider-text">{group.date}</span>
            </div>

            {group.items.map((msg, index) => {
              const prevMsg = index > 0 ? group.items[index - 1] : null;
              const isConsecutive = Boolean(
                prevMsg &&
                prevMsg.sender_id === msg.sender_id &&
                Math.abs(new Date(msg.created_at).getTime() - new Date(prevMsg.created_at).getTime()) < 5 * 60 * 1000
              );
              return (
                <MessageItem
                  key={msg.id}
                  message={msg}
                  currentUserId={currentUserId}
                  members={members}
                  isConsecutive={isConsecutive}
                  onToggleReaction={onToggleReaction}
                  onEditMessage={onEditMessage}
                  onDeleteMessage={onDeleteMessage}
                  onOpenUserProfile={onOpenUserProfile}
                />
              );
            })}
          </React.Fragment>
        ))
      )}

      {/* Typing Indicator */}
      {typingUserIds.length > 0 && (
        <div className="typing-bubble">
          <div className="typing-dot" />
          <div className="typing-dot" />
          <div className="typing-dot" />
          <span className="typing-text">Someone is typing...</span>
        </div>
      )}

      <div ref={bottomRef} style={{ height: 1 }} />

      {/* Scroll to bottom button */}
      {showScrollBottom && (
        <button
          onClick={() => scrollToBottom('smooth')}
          className="btn-icon btn-primary"
          style={{
            position: 'absolute',
            bottom: '24px',
            right: '24px',
            borderRadius: '50%',
            boxShadow: 'var(--shadow-lg)',
            zIndex: 10,
          }}
          title="Scroll to bottom"
        >
          <ArrowDown size={18} />
        </button>
      )}
    </div>
  );
};

